entries[246067] = { ["name"] = "Pearlescent Krolusk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Introduced as an invasive species to K'aresh, Krolusk have found some use as beasts of burden.\"\nDrop:\nUrmag\nZone:\nK'aresh" }
entries[246071] = { ["name"] = "Mana-Seamster's Arcane-Needle", ["text"] = "Binds when picked up\nTwo-Hand Staff\n25 - 34 Damage Speed 3.60\n(8.2 damage per second)\n+98 Intellect\n+99 Stamina\n+ 29 Critical Strike\n+ 15 Versatility\nDurability 120 / 120\nEquip: Your spells have a chance to grant you a stack of Ether-Plate up to 5.\n\nThe next time you would take direct targeted damage, consume an Ether-Plate and reduce that instance of damage by 50% up to 657 .\nSell Price:" }
entries[246072] = { ["name"] = "Intricate Everchill Pearl", ["text"] = "Binds when picked up\nEquip: Grants 2 additional ranks of Volatile Magics .\n\nVolatile Magics\nYour critical strikes have a chance to create a burst of magic, inflicting [(342% Attack/Spell Power)] Arcane damage to enemies within 6 yards of your target.\n\nNaran's Everdisc now always critically strikes Fel Touched enemies.\nRequires level 10 to 90 ( 90)" }
entries[246073] = { ["name"] = "Intricate Rage of the Tides", ["text"] = "Binds when picked up\nEquip: Grants 2 additional ranks of Touch of Malice .\n\nTouch of Malice\nYour and your minions' damaging spells and abilities periodically apply Fel Touched to enemies. The infernal dreadlord summoned by Twisted Crusade always critically strikes Fel Touched enemies.\n\nFel Touched\nEvery 4 seconds, the targets bursts, damaging nearby enemies for 3% of damage taken over the last 4 seconds.\n\nDamage reduced beyond 5 targets.\nRequires level 10 to 90 ( 90)" }
entries[246074] = { ["name"] = "Intricate Sundered Comet", ["text"] = "Binds when picked up\nEquip: Grants 2 additional ranks of Terror From Below .\n\nTerror From Below\nYour abilities periodically draw the attention of a behemoth from the deep that seeks your enemy, inflicting [(440% Attack/Spell Power)] Nature damage split evenly between all enemies nearby.\n\nWhen Terror From Below strikes a Fel Touched enemy it causes Deepsurge Crash , damaging all nearby enemies for [(440% Attack/Spell Power)] nature damage.\nRequires level 10 to 90 ( 90)" }
entries[246075] = { ["name"] = "Intricate Gelmogg's Fractured Skull", ["text"] = "Binds when picked up\nEquip: Grants 2 additional ranks of Highmountain Fortitude .\n\nHighmountain Fortitude\nOnce every 12 sec, you begin accumulating 3% of all damage taken as Fortitude . After 8 sec, Fortitude becomes a protective barrier, absorbing the amount accumulated for 4 sec.\nRequires level 10 to 90 ( 90)" }
entries[246076] = { ["name"] = "Intricate Ettin Bone Fragment", ["text"] = "Binds when picked up\nEquip: Grants 2 additional ranks of Souls of the Caw .\n\nSouls of the Caw\nYour spells and abilities have a chance to summon a flock of spirit eagles that dive bomb nearby enemies, exploding on impact to heal allies and inflict [[2 * (368% Attack/Spell Power)]][[(368% Attack/Spell Power)]] Nature damage to enemies within 5 yards.\nRequires level 10 to 90 ( 90)" }
entries[246077] = { ["name"] = "Intricate Gleaming Iron Spike", ["text"] = "Binds when picked up\nEquip: Grants 2 additional ranks of Arcane Aegis .\n\nArcane Aegis\nWhile moving backward, you channel an Arcane Aegis , absorbing up to [(2100% Attack/Spell Power)] damage but reducing your movement speed by 80%. While not channeling Arcane Aegis , it regenerates at 5% per second. If the Arcane Aegis is shattered, it becomes unusable for 30 sec.\nRequires level 10 to 90 ( 90)" }
entries[246078] = { ["name"] = "Intricate Xakal's Determination", ["text"] = "Binds when picked up\nEquip: Grants 2 additional ranks of Temporal Retaliation .\n\nTemporal Retaliation\nWhen you absorb damage, inflict [(31% Attack/Spell Power)] Arcane damage back to the attacker and reduce their attack speed by 20% for 3 sec.\nRequires level 10 to 90 ( 90)" }
