entries[246304] = { ["name"] = "Darkmoon Dominion: Hunt", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have the chance to grant 12 secondary stats for 15 sec based on the target creature's type.\n\nThis effect is augmented by Darkmoon Sigil: Hunt.\nSell Price:" }
entries[246305] = { ["name"] = "Darkmoon Dominion: Blood", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 [Agility or Strength or Intellect]\nEquip: Your damaging spells and abilities have the chance to grant Farstrider's Guile , increasing your lowest secondary stat by 31 for 15 sec.\n\nWhen an allied player dies, gain 4 of your highest secondary stat for 15 sec. This effect can only occur once every 5 min.\n\nThis effect is augmented by Darkmoon Sigil: Blood.\nSell Price:" }
entries[246306] = { ["name"] = "Darkmoon Dominion: Rot", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 [Agility or Strength or Intellect]\nEquip: Afflict your target with Rotting Roots dealing 3 Nature Damage every 2 seconds for 6 sec. This effect stacks up to 10 times. New stacks do not refresh applied stacks.\n\nThis effect is augmented by Darkmoon Sigil: Rot.\nSell Price:" }
entries[246307] = { ["name"] = "Darkmoon Dominion: Void", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 [Agility or Strength or Intellect]\nEquip: Your damaging spells and abilities have the chance to embolden you in Void Glass granting 9 Versatility over 15 sec. Multiple applications can overlap.\n\nThis effect is augmented by Darkmoon Sigil: Void.\nSell Price:" }
entries[246314] = { ["name"] = "Burbling Blob of Paint", ["text"] = "Binds to Warband\nUse: Rinse this the next time you go for a swim to reveal what wriggles in the paint blob. Warning, you may get wet as well.\nRight Click to summon and dismiss your Painter Frog.\nRequires level 1 to 90 ( 90)\nSell Price:" }
