entries[246363] = { ["name"] = "Sinara Berry", ["text"] = "Quest Item\nRequires level 80 to 83 ( 83)\n\"Special care is required when handling these deep, red berries. If done incorrectly, it makes a potent poison. Delicious, albeit rather deadly.\"" }
