entries[246445] = { ["name"] = "Reins of the Royal Voidwing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A cosmic terror warped and hardened by the cruelties of the Nexus-King, now oathsworn to your service.\"\nQuest:\nA Twilight Oath's End" }
entries[246446] = { ["name"] = "Mark of the Twilight Oath", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 80 to 80 ( 80)\n\"A token of the Nexus-King's ancient betrayal. You should take this back to Ve'nari in the Oasis.\"" }
entries[246447] = { ["name"] = "Apprentice's Scribbles", ["text"] = "Use: Combine 5 Apprentice's Scribbles to create a Artisan's Ledger.\nFinishing Crafting Reagent\n+100 Recipe Difficulty\nWhen crafting: Increases Skill by 5.\nUsable with: Many Midnight recipes across all professions.\n\"Useful in small doses. Can be bought and sold on the Auction House.\"\nSell Price:" }
