entries[246449] = { ["name"] = "Mentor's Helpful Handiwork", ["text"] = "Use: Combine 5 Mentor's Helpful Handiwork to create a Artisan's Consortium Gold Star.\nFinishing Crafting Reagent\n+100 Recipe Difficulty\nWhen crafting: Increases Skill by 20.\nUsable with: Many Midnight recipes across all professions.\n\"No need to reinvent the wheel. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[246450] = { ["name"] = "Artisan's Consortium Gold Star", ["text"] = "Binds when picked up\nFinishing Crafting Reagent\n\nWhen crafting: Increases Skill by 50.\nUsable with: Many Midnight recipes across all professions.\n\"An award befitting a crafter of great esteem.\"\nSell Price:" }
