entries[246731] = { ["name"] = "Dusk Grimlynx", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Famously adept at hunting at dusk as the light of dusk blends this grimlynx's foliage with its surroundings.\"\nQuest:\nHistory Lesson\nZone:\nHarandar" }
entries[246732] = { ["name"] = "Void-Forged Overseer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"After the Sepulcher of the First Ones was opened, this construct of the First Ones was stolen by the brokers and sold to the ethereals in a transaction at the Veiled Market. Under the ethereals' ingenious modifications, it integrated the mysteries of the Aether, gliding through the air with extraordinary elegance, leaving behind a trail of shimmering stardust.\"\nPromotion" }
entries[246734] = { ["name"] = "Fierce Grimlynx", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 16 with the Hara'ti.\n\n\"This grimlynx has seen many battles against the creatures in the Rift of Aln.\"\nVendor:\nNaynar\nZone:\nHarandar\nCost:\n6000" }
entries[246735] = { ["name"] = "Rootstalker Grimlynx", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"With fur to match the deep roots and armor to match the vast foliage, these Grimlynx are equipped to be some of the ultimate hunters of Harandar.\"\nDrop:\nHarandar Rare Creatures" }
entries[246736] = { ["name"] = "Ivory Grimlynx", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Ivory grimlynxes have a strong independent streak. It takes an especially brave Haranir to ride them.\"\nAchievement:\nAllied Race: Haranir\nCategory:\nMidnight" }
