entries[246903] = { ["name"] = "Guise of the Phase Diver", ["text"] = "Binds when picked up\nToy\nUse: Enter an ethereal state of energy.\n\"Witness infinity and total emptiness at the same time.\"" }
entries[246904] = { ["name"] = "Unseen Path of the Phase Stalker", ["text"] = "Binds when picked up\nUse: Summons a rideable phase-lost warp stalker in K'aresh. This is a very, VERY fast mount. (2 Min Cooldown)\n\"Navigate the sands of K'aresh as the Wastelanders have learned.\"" }
entries[246905] = { ["name"] = "Overtuned K'areshi Goggles", ["text"] = "Binds when picked up\nToy\nUse: View the world through K'areshi sensibilities. (30 Min Cooldown)\n\"Beauty is ethereal. Always.\"" }
entries[246907] = { ["name"] = "Broker Supply Crate", ["text"] = "Binds when picked up\nToy\nUse: Carry your crate full of Tazaveshi supplies and knick-knacks. (10 Sec Cooldown)" }
entries[246908] = { ["name"] = "K'areshi Supply Crate", ["text"] = "Binds when picked up\nToy\nUse: Carry your crate full of K'areshi supplies and doodads. (10 Sec Cooldown)" }
entries[246910] = { ["name"] = "Vintage Vintage", ["text"] = "Quest Item\n\"Elrendar Reserve, 25.\"" }
entries[246911] = { ["name"] = "Discarded Wand", ["text"] = "Quest Item\n\"A plain, dormant wand. A note is attached to its handle: \"DEEMED UNSUITABLE. RECYCLE.\"\"" }
entries[246912] = { ["name"] = "Unstable Arcana", ["text"] = "Quest Item\n\"The glass vial pulses with shifting arcane energy, unpredictable and uncontrollable.\"" }
entries[246913] = { ["name"] = "Magical Mango", ["text"] = "Quest Item\n\"Likely pilfered from a Magister's party table.\"" }
entries[246914] = { ["name"] = "Perfectly Fine Grain", ["text"] = "Quest Item\n\"Triple inspected, this grain is surely safe to handle and consume.\"" }
entries[246915] = { ["name"] = "Arsenal: Ethereal Weaponry", ["text"] = "Binds when picked up\nUse: Collect the appearances of the Ethereal Weaponry weapon set." }
entries[246917] = { ["name"] = "Thunder-Ridged Elekk", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Even infusion with demonic magics could not break the spirits of these majestic beasts, and their twisted forms were never integrated into the Legion's service.\"\nTrading Post" }
entries[246919] = { ["name"] = "Cinder-Seared Elekk", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Burning Legion sought to destroy, steal or corrupt anything that brought joy to the draenei, and the elekks of Draneor were no exception.\"\nTrading Post" }
entries[246920] = { ["name"] = "Void-Razed Elekk", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Their temperament is as wild as the twisted forces that warped their creation and they only serve who they choose.\"\nTrading Post" }
entries[246921] = { ["name"] = "Legion-Forged Elekk", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Burning Legion envied the draenei's bond with the elekks of Draenor. Many demonic beast-masters warped the breed to serve their needs, but none could control them.\"\nTrading Post" }
entries[246923] = { ["name"] = "Frillfish Fillet", ["text"] = "Quest Item\n\"Prized for its tender texture, the fillet has wave-like marbling and a subtly briny flavor.\"" }
entries[246924] = { ["name"] = "Root Drift Jelly", ["text"] = "Quest Item\n\"Sweet and shimmering, it is rumored to tingle on the tongue and glow faintly in the dark.\"" }
entries[246926] = { ["name"] = "Nutrient-Rich Soil", ["text"] = "Quest Item\n\"Soil packed in nutrients needed for a growing rutaani. A meal replacement for those not inclined to consuming solids.\"" }
entries[246934] = { ["name"] = "Small Covered Wooden Table", ["text"] = "3\nHousing Decor\nBinds to Warband\nUse: This Decor will be added immediately on purchase to your House Chest.\nSell Price:" }
