entries[246936] = { ["name"] = "Resonant Epoch Memento", ["text"] = "Binds when picked up\nUse: Fuse this Epoch Memento with your artifact weapon, creating a ripple across all timelines and versions of \"you\".\n\nThis powerful relic resonates with your Warband, permanently increasing all experience gains in Legion Remix by 1%.\nRequires level 10 to 90 ( 90)\n\"A tiny piece of an epoch story.\"" }
entries[246937] = { ["name"] = "Perfected Epoch Memento", ["text"] = "Binds when picked up\nUse: Fuse this Epoch Memento with your artifact weapon, creating a ripple across all timelines and versions of \"you\".\n\nThis perfect relic resonates with your Warband, permanently increasing all experience gains in Legion Remix by 10%.\nRequires level 10 to 90 ( 90)\n\"A crucial piece of an epoch story.\"" }
entries[246939] = { ["name"] = "Essence-Hunter's Eyeglass", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Intellect]\nEquip: Your harmful spells and ranged abilities critical strikes have a high chance to grant you Arcane Hunter up to 5 times, increasing your Critical Strike rating by 7 per stack for 8 sec.\nSell Price:" }
entries[246940] = { ["name"] = "Manaforged Aethercell", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 Intellect\nEquip: Your healing abilities have a chance to power the Aethercell increasing your Mastery by 116 , decreasing by ( 116 / 15) each sec. Lasts 15 sec.\nSell Price:" }
entries[246941] = { ["name"] = "Symbiotic Ethergauze", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+44 Stamina\nEquip: Blocking, parrying, or dodging has a chance to awaken the Gauze causing it to lash out dealing 1746 Arcane damage split between nearby enemies while shielding you for 10113 damage for 15 sec.\nSell Price:" }
entries[246942] = { ["name"] = "Corpse Rind", ["text"] = "Quest Item\n\"Freshly slain, the plant-based flesh still shines with a moist glow.\"" }
entries[246944] = { ["name"] = "Mind-Fracturing Odium", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength]\nEquip: Your harmful abilities may cause your mind to tear piece by piece. At the tenth tear, you succumb to Arcane Insanity granting you 55 Haste while periodically recovering your sanity over time.\n\nSlaying an enemy or witnessing an ally's death instantly tears at your sanity.\n\"Were there always this many tentacles around here?\"\nSell Price:" }
entries[246945] = { ["name"] = "Incorporeal Essence-Gorger", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength or Intellect]\nUse: Rip magical essence out of your target and consume it dealing ( 833 * 1 ) Arcane damage while granting you 120 of your lowest secondary stat for 20 sec.\n\nIf the target was an Ethereal, your highest secondary stat is increased instead. (2 Min Cooldown)\nSell Price:" }
entries[246947] = { ["name"] = "Twisted Mana Sprite", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 28 Versatility\nEquip: Your healing spell and abilities have a very high chance to summon a Twisted Mana Sprite to assist you in combat for 10 sec. Twisted Mana Sprite periodically heal a random nearby ally for ( 629 * 1 ). Overhealing is converted into an absorb shield for 5 sec.\nSell Price:" }
